mapper.select:
SELECT pi.id, pi.invoice_no AS invoiceNo, pi.invoice_date AS invoiceDate, so.order_code AS salesOrderCode, c.customer_name AS companyName, COUNT(sid.id) AS detailCount, GROUP_CONCAT(sid.item_name SEPARATOR '；') AS itemName, GROUP_CONCAT(sid.specification SEPARATOR '；') AS specification, GROUP_CONCAT(DISTINCT sid.unit SEPARATOR '；') AS unit, SUM(sid.quantity) AS quantity, CASE WHEN COUNT(sid.id) = 1 THEN MAX(sid.unit_price) ELSE NULL END AS unitPriceInclusiveTax, SUM(sid.amount_inclusive_tax) AS amountInclusiveTax, SUM(sid.amount_exclusive_tax) AS amountExclusiveTax, SUM(sid.tax_amount) AS taxAmount, DATEDIFF(pi.invoice_date, so.order_date) AS avgInvoiceDays, (so.total_amount - IFNULL(( SELECT SUM(amount) FROM sales_invoices si2 WHERE si2.sales_order_id = so.id AND si2.is_deleted = 0 ), 0)) AS pendingInvoiceAmount FROM sales_invoices pi INNER JOIN sales_invoice_details sid ON pi.id = sid.invoice_id LEFT JOIN sales_orders so ON pi.sales_order_id = so.id LEFT JOIN customers c ON pi.customer_id = c.id
pi.id IN
#{id}
GROUP BY pi.id, pi.invoice_no, pi.invoice_date, so.order_code, c.customer_name, so.order_date, so.total_amount, so.id ORDER BY FIELD(pi.id,
#{id}
)
